// Chunky, readable player cars with animated wheels and team-colored boost cores
function buildCar(primary,accent){const root=new THREE.Group(),paint=mat(primary,.28,.42),trim=mat(0x101b23,.36,.25),glass=mat(0x9fe7f1,.16,.28,{emissive:0x1e5566,emissiveIntensity:.42}),glow=mat(accent,.24,.25,{emissive:accent,emissiveIntensity:1.5});
 const chassis=new THREE.Mesh(new THREE.BoxGeometry(1.75,.48,2.85),paint);chassis.position.y=.56;chassis.castShadow=true;root.add(chassis);
 const hood=new THREE.Mesh(new THREE.BoxGeometry(1.65,.18,1.05),glow);hood.position.set(0,.84,-.63);hood.castShadow=true;root.add(hood);
 const cabin=new THREE.Mesh(new THREE.BoxGeometry(1.22,.55,1.18),glass);cabin.position.set(0,1.03,.22);cabin.castShadow=true;root.add(cabin);
 const roof=new THREE.Mesh(new THREE.BoxGeometry(1.25,.12,.92),paint);roof.position.set(0,1.34,.23);root.add(roof);
 const bumperF=new THREE.Mesh(new THREE.BoxGeometry(1.9,.2,.22),trim);bumperF.position.set(0,.39,-1.47);root.add(bumperF);const bumperB=bumperF.clone();bumperB.position.z=1.47;root.add(bumperB);
 for(let x of [-.92,.92])for(let z of [-.88,.9]){const tire=new THREE.Mesh(new THREE.CylinderGeometry(.33,.33,.2,12),trim);tire.rotation.z=Math.PI/2;tire.position.set(x,.34,z);tire.castShadow=true;root.add(tire);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.14,.14,.21,10),glow);hub.rotation.z=Math.PI/2;hub.position.set(x,.34,z);root.add(hub)}
 for(let x of [-.59,.59]){const lamp=new THREE.Mesh(new THREE.BoxGeometry(.37,.1,.07),mat(0xe4fbff,.17,.1,{emissive:0xb8f7ff,emissiveIntensity:2}));lamp.position.set(x,.66,-1.46);root.add(lamp)}
 const exhaust=new THREE.Mesh(new THREE.ConeGeometry(.34,1.3,12),new THREE.MeshBasicMaterial({color:accent,transparent:true,opacity:.75}));exhaust.rotation.x=-Math.PI/2;exhaust.position.set(0,.49,1.95);exhaust.visible=false;root.add(exhaust);
 scene.add(root);return {root,exhaust,accent};}
const playerCar=buildCar(0x18b9dd,0x66efff),botCar=buildCar(0xeb6849,0xffa05f);
// Game ball: glossy shell with contrasting inset panels
const ballRoot=new THREE.Group(),ballRadius=1.12;const ballShell=new THREE.Mesh(new THREE.SphereGeometry(ballRadius,32,24),mat(0xf1f6f3,.23,.16,{emissive:0x31464b,emissiveIntensity:.12}));ballShell.castShadow=true;ballShell.receiveShadow=true;ballRoot.add(ballShell);
const ballDark=mat(0x1a3039,.4,.18);const directions=[];for(let i=0;i<12;i++){const phi=Math.acos(1-2*(i+.5)/12),theta=Math.PI*(1+Math.sqrt(5))*i;directions.push(new THREE.Vector3(Math.sin(phi)*Math.cos(theta),Math.cos(phi),Math.sin(phi)*Math.sin(theta)))}
for(const n of directions){const patch=new THREE.Mesh(new THREE.CircleGeometry(.25,5),ballDark);patch.position.copy(n.clone().multiplyScalar(ballRadius*.985));patch.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),n);ballRoot.add(patch)}
const ballGlow=new THREE.PointLight(0xbdeeff,2.7,5);ballRoot.add(ballGlow);scene.add(ballRoot);
// Subtle boost particles; pooled and recycled for low overhead
const particleGeo=new THREE.SphereGeometry(.11,7,6),particles=[];for(let i=0;i<46;i++){const p=new THREE.Mesh(particleGeo,new THREE.MeshBasicMaterial({color:i%2?0x66efff:0xffffff,transparent:true,opacity:.82}));p.visible=false;scene.add(p);particles.push({mesh:p,life:0,velocity:new THREE.Vector3()})}let particleIndex=0;
const ball={pos:new THREE.Vector3(0,1.12,0),vel:new THREE.Vector3(),spin:new THREE.Vector3()};
function makeCarState(z,yaw){return {pos:new THREE.Vector3(0,.5,z),vel:new THREE.Vector3(),yaw,grounded:true,jumpCount:0,boost:75,steer:0}}
let player=makeCarState(22,0),bot=makeCarState(-22,Math.PI),scorePlayer=0,scoreBot=0,elapsed=0,active=false,paused=false,finished=false,kickoff=0,goalFreeze=0;
const keys=new Set(),vecForward=new THREE.Vector3(),tmp=new THREE.Vector3(),clockObj=new THREE.Clock();
function resetPositions(){player=makeCarState(0,0);player.pos.z=22;bot=makeCarState(0,Math.PI);bot.pos.z=-22;ball.pos.set(0,1.12,0);ball.vel.set(0,0,0);ball.spin.set(0,0,0);kickoff=1.35;}
function startMatch(){scorePlayer=0;scoreBot=0;elapsed=0;finished=false;paused=false;active=true;resetPositions();updateScore();document.querySelector('#overlay').classList.add('hidden');document.querySelector('#pause-button').innerHTML='Ⅱ &nbsp; PAUSE';}
function updateScore(){document.querySelector('#player-score').textContent=scorePlayer;document.querySelector('#bot-score').textContent=scoreBot;document.querySelector('#player-dots').querySelectorAll('i').forEach((d,i)=>d.classList.toggle('on',i<scorePlayer));document.querySelector('#bot-dots').querySelectorAll('i').forEach((d,i)=>d.classList.toggle('on',i<scoreBot));}
function forwardOf(yaw){return new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw))}
function driveCar(state,throttle,steer,boosting,dt,car,ai=false){const f=forwardOf(state.yaw);const speed=state.vel.dot(f);const steeringFactor=THREE.MathUtils.clamp(Math.abs(speed)/4,.25,1.15);state.yaw+=steer*2.45*steeringFactor*dt*(speed<-.4?-1:1);
 const forward=forwardOf(state.yaw);if(throttle){state.vel.addScaledVector(forward,throttle*(boosting?35:23)*dt)}
 if(boosting&&state.boost>0&&throttle>0){state.boost=Math.max(0,state.boost-35*dt);state.vel.addScaledVector(forward,25*dt)}else if(!ai){state.boost=Math.min(100,state.boost+9*dt)}
 const fwdSpeed=state.vel.dot(forward);const side=state.vel.clone().addScaledVector(forward,-fwdSpeed);side.multiplyScalar(Math.max(0,1-5.8*dt));state.vel.copy(side).addScaledVector(forward,fwdSpeed);
 state.vel.multiplyScalar(Math.max(0,1-(throttle===0?1.1:.22)*dt));const max=boosting?25:17;if(state.vel.length()>max)state.vel.setLength(max);
 state.pos.addScaledVector(state.vel,dt);state.pos.x=THREE.MathUtils.clamp(state.pos.x,-15.65,15.65);state.pos.z=THREE.MathUtils.clamp(state.pos.z,-29.4,29.4);
 if(state.pos.y>.5){state.vel.y-=19*dt;state.pos.y+=state.vel.y*dt;if(state.pos.y<=.5){state.pos.y=.5;state.vel.y=0;state.grounded=true;state.jumpCount=0}}
 car.root.position.copy(state.pos);car.root.rotation.set(0,state.yaw,0);car.exhaust.visible=!!(boosting&&state.boost>0&&throttle>0);car.exhaust.scale.setScalar(.78+Math.random()*.38);
}
function jump(state){if(!active||paused||finished)return;if(state.grounded){state.vel.y=9.4;state.pos.y+=.04;state.grounded=false;state.jumpCount=1}else if(state.jumpCount===1){const f=forwardOf(state.yaw);state.vel.addScaledVector(f,8);state.vel.y=Math.max(state.vel.y,7);state.jumpCount=2}}
function moveBot(dt){const targetGoalZ=31.8;const toGoal=new THREE.Vector3(0,0,targetGoalZ-ball.pos.z);const goalDir=toGoal.lengthSq()>.1?toGoal.normalize():new THREE.Vector3(0,0,1);const target=ball.pos.clone().addScaledVector(goalDir,-2.05);target.x=THREE.MathUtils.clamp(target.x,-12.5,12.5);target.z=THREE.MathUtils.clamp(target.z,-27,27);
 let dx=target.x-bot.pos.x,dz=target.z-bot.pos.z;let desired=Math.atan2(-dx,-dz);let delta=Math.atan2(Math.sin(desired-bot.yaw),Math.cos(desired-bot.yaw));let steer=THREE.MathUtils.clamp(delta*2.3,-1,1);const distance=Math.hypot(dx,dz);const throttle=distance>1.3?1:(distance<.7?-.18:.4);const boosting=distance>9&&Math.abs(delta)<.48&&bot.boost>0;if(boosting)bot.boost-=24*dt;else bot.boost=Math.min(70,bot.boost+8*dt);driveCar(bot,throttle,steer,boosting,dt,botCar,true)}
function hitCar(car){const center=car.pos.clone();center.y+=.55;const delta=ball.pos.clone().sub(center);const dist=delta.length(),min=ballRadius+1.03;if(dist>=min)return;const normal=dist>.001?delta.normalize():new THREE.Vector3(0,0,1);const penetration=min-dist;ball.pos.addScaledVector(normal,penetration+.012);const relative=ball.vel.clone().sub(car.vel);const hit=Math.max(0,-relative.dot(normal));ball.vel.addScaledVector(normal,hit*1.35+5.4);ball.vel.addScaledVector(car.vel,.58);ball.vel.y+=Math.max(0,car.vel.length()*.13);if(ball.vel.length()>29)ball.vel.setLength(29)}
function playGoalSound(){try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),now=ctx.currentTime;[440,554,659,880].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(f,now+i*.09);g.gain.setValueAtTime(.0001,now+i*.09);g.gain.exponentialRampToValueAtTime(.12,now+i*.09+.025);g.gain.exponentialRampToValueAtTime(.0001,now+i*.09+.42);o.connect(g);g.connect(ctx.destination);o.start(now+i*.09);o.stop(now+i*.09+.45)})}catch(e){}}
function scoreGoal(who){if(who==='player')scorePlayer++;else scoreBot++;updateScore();goalFreeze=2.15;kickoff=2.15;ball.vel.set(0,0,0);player.vel.multiplyScalar(.25);bot.vel.multiplyScalar(.25);document.querySelector('#goaltext').textContent=who==='player'?'GOOOAL!':'BOT SCORES';const flash=document.querySelector('#goalflash');flash.className='goalflash show '+(who==='player'?'player':'bot');setTimeout(()=>flash.classList.remove('show'),1250);playGoalSound();if(scorePlayer>=3||scoreBot>=3){finished=true;setTimeout(showEnd,1450)}}
function showEnd(){const win=scorePlayer>=3;document.querySelector('#eyebrow').textContent=win?'SERIES WON':'SERIES LOST';document.querySelector('#title').innerHTML=win?'NICE<span>SHOT.</span>':'BOT<span>WINS.</span>';document.querySelector('#subtitle').textContent=win?`You took the series ${scorePlayer}–${scoreBot}. That was all boost, all skill.`:`The bot took it ${scoreBot}–${scorePlayer}. Run it back and reclaim the arena.`;document.querySelector('#play-button').textContent='REMATCH  →';document.querySelector('.panelfoot').textContent='FIRST TO THREE · THE ARENA IS YOURS';document.querySelector('#overlay').classList.remove('hidden');active=false}
function updateBall(dt){if(kickoff>0){kickoff-=dt;ball.vel.multiplyScalar(.93);return}ball.vel.y-=12.6*dt;ball.pos.addScaledVector(ball.vel,dt);ball.vel.multiplyScalar(Math.max(0,1-.13*dt));ball.spin.x+=ball.vel.z*dt*.22;ball.spin.z-=ball.vel.x*dt*.22;
 if(ball.pos.y<ballRadius){ball.pos.y=ballRadius;if(ball.vel.y<0)ball.vel.y*=-.67;ball.vel.x*=.985;ball.vel.z*=.985;if(Math.abs(ball.vel.y)<.8)ball.vel.y=0}
 if(Math.abs(ball.pos.x)>15.8){ball.pos.x=Math.sign(ball.pos.x)*15.8;ball.vel.x*=-.72}
 // Goal mouth is open between the posts; otherwise end boards rebound the ball.
 if(ball.pos.z < -31.85&&Math.abs(ball.pos.x)<4.05&&ball.pos.y<4.5){scoreGoal('player')}else if(ball.pos.z>31.85&&Math.abs(ball.pos.x)<4.05&&ball.pos.y<4.5){scoreGoal('bot')}else if(Math.abs(ball.pos.z)>31.65){ball.pos.z=Math.sign(ball.pos.z)*31.65;ball.vel.z*=-.72}
 hitCar(player);hitCar(bot);ballRoot.position.copy(ball.pos);ballRoot.rotation.set(ball.spin.x,0,ball.spin.z);
}
function emitBoost(state,car,dt){if(!car.exhaust.visible)return;for(let i=0;i<2;i++){const p=particles[particleIndex++%particles.length],f=forwardOf(state.yaw),origin=state.pos.clone().add(new THREE.Vector3(0,.48,0)).addScaledVector(f,-1.8);p.mesh.position.copy(origin);p.mesh.visible=true;p.life=.3+Math.random()*.22;p.velocity.copy(f).multiplyScalar(-2-Math.random()*3);p.velocity.y=(Math.random()-.5)*2;p.mesh.scale.setScalar(.7+Math.random()*.8)}}
function animateParticles(dt){for(const p of particles){if(!p.mesh.visible)continue;p.life-=dt;p.mesh.position.addScaledVector(p.velocity,dt);p.mesh.scale.multiplyScalar(.96);if(p.life<=0)p.mesh.visible=false}}

playerCar.root.position.copy(player.pos);playerCar.root.rotation.y=player.yaw;botCar.root.position.copy(bot.pos);botCar.root.rotation.y=bot.yaw;ballRoot.position.copy(ball.pos);
function togglePause(){if(!active||finished)return;paused=!paused;if(paused){document.querySelector('#eyebrow').textContent='TAKE A BREATHER';document.querySelector('#title').innerHTML='GAME<span>PAUSED</span>';document.querySelector('#subtitle').textContent='The ball can wait. Ready to get back in the game?';document.querySelector('#play-button').textContent='RESUME  →';document.querySelector('.panelfoot').textContent='PRESS P OR CLICK RESUME TO CONTINUE';document.querySelector('#overlay').classList.remove('hidden');document.querySelector('#pause-button').innerHTML='▶ &nbsp; RESUME'}else{document.querySelector('#overlay').classList.add('hidden');document.querySelector('#pause-button').innerHTML='Ⅱ &nbsp; PAUSE'}}
document.querySelector('#play-button').addEventListener('click',()=>{if(paused){togglePause();return}startMatch()});document.querySelector('#pause-button').addEventListener('click',togglePause);
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key==='p'||key==='escape'){togglePause();return}keys.add(key);if(key===' '&&active&&!paused)jump(player)});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
for(const button of document.querySelectorAll('[data-key]')){const k=button.dataset.key;const down=e=>{e.preventDefault();keys.add(k);button.classList.add('active');if(k==='space')jump(player)};const up=e=>{e.preventDefault();keys.delete(k);button.classList.remove('active')};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up)}
function formatTime(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
const cameraTarget=new THREE.Vector3(),lookTarget=new THREE.Vector3();let lastFrame=performance.now();
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-lastFrame)/1000);lastFrame=now;
 if(active&&!paused&&!finished){elapsed+=dt;if(goalFreeze>0)goalFreeze-=dt;
  if(goalFreeze<=0){const throttle=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0);const steer=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);const boosting=keys.has('shift');driveCar(player,throttle,steer,boosting,dt,playerCar);moveBot(dt);emitBoost(player,playerCar,dt);emitBoost(bot,botCar,dt);updateBall(dt);animateParticles(dt)}
  document.querySelector('#clock').textContent=formatTime(elapsed);document.querySelector('#boost-value').textContent=Math.round(player.boost);document.querySelector('#boost-meter').style.width=player.boost+'%';document.querySelector('#speed-value').textContent=String(Math.round(player.vel.length()*9)).padStart(3,'0');
 }
 const f=forwardOf(player.yaw);cameraTarget.copy(player.pos).add(new THREE.Vector3(Math.sin(player.yaw)*10,5.1,Math.cos(player.yaw)*10));if(!active){const t=now*.00012;cameraTarget.set(Math.sin(t)*38,22,Math.cos(t)*38)}camera.position.lerp(cameraTarget,1-Math.exp(-dt*3.1));lookTarget.copy(player.pos).addScaledVector(f,7);lookTarget.y+=1.2;if(!active)lookTarget.set(0,0,0);camera.lookAt(lookTarget);
 renderer.render(scene,camera)}
requestAnimationFrame(frame);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script>
</body></html>

