function playGoalSound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const ctx=new Audio();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sawtooth';osc.frequency.setValueAtTime(420,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(880,ctx.currentTime+.22);osc.frequency.exponentialRampToValueAtTime(180,ctx.currentTime+.8);gain.gain.setValueAtTime(.12,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.85);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.86);osc.onended=()=>ctx.close()}catch{}}
